(async () => {
      // Only allow activity in the iframe (not in the top-level window)
      if (window.self === window.top) return;

      const scriptPath = "https://sec.webeyez.com/js/dcbe3284-5fa8-4283-95bd-4a276ba5eedd";
      const scope = `${scriptPath}/`;
      const urlParams = new URLSearchParams(window.location.search);
      // MUST have a deterministic expected version
      const wzVersion = urlParams.get('wz-ver') || "2026.04.21.d40308b";
      const FEATURE_BULK_EVENTS_TRACKER_CHANGE_CLEAR = false ?? false;
      const swUrl = `${scriptPath}/wz_ww.js?wz-ver=${encodeURIComponent(wzVersion)}`;

      const norm = (u) => {
        try { return new URL(u, location.href).href; } catch { return String(u); }
      };

      try {
        // Try to get existing registration first
        const abs = (u) => new URL(u, location.href).href;
        const desiredScope = abs(scope);

        // Prefer precise registration lookup, fallback to prefix match scan
        let reg = await navigator.serviceWorker.getRegistration(desiredScope);
        if (!reg) {
          const regs = await navigator.serviceWorker.getRegistrations();
          reg = regs
            .filter(r => desiredScope === r.scope || desiredScope.startsWith(r.scope))
            .sort((a,b) => b.scope.length - a.scope.length)[0];        
        }
        if (!reg) {
          reg = await registerServiceWorker(swUrl, { scope: desiredScope });
        }

        // Attach updatefound before triggering update so we don't miss it
        reg && reg.addEventListener("updatefound", () => {
          const sw = reg.installing;
          if (!sw) return;
          sw.addEventListener("statechange", () => {
            if (sw.state === "installed" || sw.state === "activating" || sw.state === "activated") {
              enforceVersion(sw);
            }
          });
        });

        // Ask browser to check for update after listener is attached
        try { await reg.update(); } catch {}

        // If there's already a waiting SW (from a previous update), enforce it now
        if (reg?.waiting) {
          try { await enforceVersion(reg.waiting); } catch {}
        }

        if (reg?.installing) {
          try { await enforceVersion(reg.installing); } catch {}
        }

        const activeUrl =
          reg?.active?.scriptURL || reg?.waiting?.scriptURL || reg?.installing?.scriptURL;

        const sameScript = activeUrl && norm(activeUrl) === norm(swUrl);

        if (!sameScript) {
          try { await reg?.unregister(); } catch {}
          reg = await registerServiceWorker(swUrl, { scope: desiredScope });
}

        // updatefound listener already attached above
        // Reload iframe when controller changes
        navigator.serviceWorker.addEventListener('controllerchange', async () => {
            // In some browsers controller can be null for a tick; wait one microtask
          await Promise.resolve();
          await notifyClientReady();
          // navigator.serviceWorker.removeEventListener('controllerchange', onControllerChange);
        }, { once: true });

        await notifyClientReady();

        // Register the 'syncQ' background sync event for reliable background flushing
        if ('SyncManager' in window && navigator.serviceWorker && navigator.serviceWorker.ready) {
          navigator.serviceWorker.ready.then(reg => {
            reg.sync && reg.sync.register('syncQ').catch(() => {
              postMessageToParent({ wzCommand: 'sendException', error: 'Failed to register syncQ background sync event.' });
            });
          });
        }

      } catch (error) {
        postMessageToParent({ wzCommand: 'sendException', error });
      }

      // Clear IndexedDB databases for this origin (sec.webeyez.com) in a cross-browser way
      async function clearWebeyezCachesIframe() {
        if (
          typeof FEATURE_BULK_EVENTS_TRACKER_CHANGE_CLEAR_MODULES ===
            "string" &&
          FEATURE_BULK_EVENTS_TRACKER_CHANGE_CLEAR_MODULES.split(",")
            .map((s) => s.trim())
            .includes("iframe")
        ) {
          // Preserve reload limiter across cleanup to avoid infinite loops
          let wzReloadCnt = null;
          try {
            wzReloadCnt = sessionStorage.getItem('wz_reload_cnt');
          } catch {}
          const deleteDatabaseAsync = async (name) => {
            return new Promise((resolve) => {
              try {
                const req = indexedDB.deleteDatabase(name);
                req.onsuccess = () => resolve(true);
                req.onerror = () => resolve(false);
                req.onblocked = () => resolve(false);
              } catch (err) {
                resolve(false);
              }
            });
          };

          try {
            if (typeof indexedDB === 'undefined' || !indexedDB) return;
            if (typeof indexedDB.databases === 'function') {
              const dbs = await indexedDB.databases();
              const targets = (dbs || [])
                .map((d) => (d && d.name ? String(d.name) : null))
                .filter((name) => name && name.startsWith('WZSR'));
              await Promise.all(targets.map((name) => deleteDatabaseAsync(name)));
            } else {
              const knownDbNames = ['WZSR_V4', 'WZSR'];
              await Promise.all(knownDbNames.map((n) => deleteDatabaseAsync(n)));
            }
          } catch {}

          // Clear CacheStorage used by Service Workers on this origin
          try {
            if ('caches' in window && window.caches && typeof window.caches.keys === 'function') {
              const keys = await window.caches.keys();
              await Promise.all((keys || []).map((key) => window.caches.delete(key).catch(() => {})));
            }
          } catch {}

          // Clear localStorage and sessionStorage for this origin
          try { window.localStorage && window.localStorage.clear(); } catch {}
          try { window.sessionStorage && window.sessionStorage.clear(); } catch {}

          // Restore reload limiter after clearing sessionStorage
          try {
            if (wzReloadCnt != null) sessionStorage.setItem('wz_reload_cnt', wzReloadCnt);
          } catch {}

          // Best-effort cookie clearing across likely domain/path combos
          try {
            const rawCookies = document.cookie ? document.cookie.split(';') : [];
            // Use a Set to ensure we only process each cookie name once
            const uniqueNames = new Set(rawCookies.map(c => c.split('=')[0].trim()));

            const host = window.location.hostname || '';
            const parts = host.split('.').filter(Boolean);
            const expirePart = '=;expires=Thu, 01 Jan 1970 00:00:00 GMT;Max-Age=0';

            // Build domain list once, outside the loop
            const domainsToTry = [null];
            if (host) {
              domainsToTry.push(host, '.' + host);
              // Only go up levels if they exist
              if (parts.length >= 2) domainsToTry.push('.' + parts.slice(-2).join('.'));
              if (parts.length >= 3) domainsToTry.push('.' + parts.slice(-3).join('.'));
            }

            uniqueNames.forEach(name => {
              // 1. Try standard paths and domains
              domainsToTry.forEach(d => {
                const baseSuffix = ';path=/' + (d ? ';domain=' + d : '');
                // Pass 1: Standard deletion
                document.cookie = name + expirePart + baseSuffix;
                // Pass 2: Secure/Cross-Site deletion
                document.cookie = name + expirePart + baseSuffix + ';SameSite=None;Secure';
              });

              // 2. Try the current specific path as a fallback
              const curPath = window.location.pathname || '/';
              if (curPath !== '/') {
                // Standard deletion for specific path
                document.cookie = name + expirePart + ';path=' + curPath;
                // Secure/Cross-Site deletion for specific path
                document.cookie = name + expirePart + ';path=' + curPath + ';SameSite=None;Secure';
              }
            });
          } catch (e) {
            // Silent fail is fine here
          }
        }
      }


      // Unified version enforcement for both installing and waiting SW
      async function enforceVersion(sw) {
        if (!sw) return null;

        const swVersion = await getActiveVersion(sw);

        // If we couldn't read version, don't force anything yet.
        if (swVersion == null) {
          if (FEATURE_BULK_EVENTS_TRACKER_CHANGE_CLEAR) {
            try { await clearWebeyezCachesIframe(); } catch {}
          }
          try { sw.postMessage({ type: "SKIP_WAITING" }); } catch {}
          return null;
        }

        if (swVersion === wzVersion) return true;

        // Version changed: optionally clean IndexedDB on this origin before swapping SW
        if (FEATURE_BULK_EVENTS_TRACKER_CHANGE_CLEAR) {
          try { await clearWebeyezCachesIframe(); } catch {}
        }
        sw.postMessage({ type: "SKIP_WAITING" });
        return false;
      }


      // Notify the parent only when the service worker is controlling the page.
      async function notifyClientReady() {
          const ctl = navigator.serviceWorker.controller;
          if (!ctl) return;

          const match = await enforceVersion(ctl);
          if (match === false) {
            // Prevent infinite reload loops if SW update fails (network issues, etc.)
            try {
              const cntRaw = sessionStorage.getItem('wz_reload_cnt');
              const reloadCount = parseInt(cntRaw == null ? '0' : cntRaw, 10) || 0;
              if (reloadCount < 3) {
                sessionStorage.setItem('wz_reload_cnt', String(reloadCount + 1));
                setTimeout(() => location.reload(), 300);
                return;
              }
            } catch (_) {}
            // Exceeded retry limit; avoid hard loop. Continue without reloading.
          }
          if (match === true) {
            // Reset reload limiter when version is good
            try { sessionStorage.removeItem('wz_reload_cnt'); } catch {}
          }
          if (match === null) {
            // couldn't determine version yet; don't loop reload
            setTimeout(() => notifyClientReady(), 300);
            return;
          }

          // Forward messages from the Service Worker to the parent.
          navigator.serviceWorker.addEventListener("message", (event) => {
            const data = parsePayload(event.data);
            if (data && data.wzCommand) {
              postMessageToParent(event.data);
            }
          });

          // Forward messages from the parent to the Service Worker.
          window.addEventListener('message', (event) => {
            const data = parsePayload(event.data);
            if (data && data.wzCommand && navigator.serviceWorker.controller) {
              postMessageToServiceWorker(event.data);
            }
          });

          // Send a one-time notification that the service worker is up.
          postMessageToServiceWorker({ wzCommand: 'clientReady' });
      }
      // Ask a specific ServiceWorker (installing/waiting/controller) for its version via MessageChannel
      function getActiveVersion(sw) {
        return new Promise((resolve) => {
          const mc = new MessageChannel();
          const timer = setTimeout(() => {
            try { mc.port1.close(); } catch {}
            resolve(null);
          }, 1500);

          mc.port1.onmessage = (e) => {
            const d = e.data;
            if (d && d.type === 'VERSION') {
              clearTimeout(timer);
              try { mc.port1.close(); } catch {}
              resolve(d.version ?? null);
            }
          };

          try {
            // Send request; the worker should reply on mc.port2
            sw.postMessage({ type: 'GET_VERSION' }, [mc.port2]);
          } catch {
            clearTimeout(timer);
            try { mc.port1.close(); } catch {}
            resolve(null);
          }
        });
      }

        function postMessageToServiceWorker(message) {
          let retries = 3;
          function sendMessage() {
            if (navigator.serviceWorker.controller) {
              navigator.serviceWorker.controller.postMessage(message);
            } else if (retries > 0) {
              retries--;
              setTimeout(sendMessage, 500);
            } else {
              postMessageToParent({ wzCommand: 'sendException', error: 'Failed to send message to Service Worker: no controller available.' });
            }
          }
          sendMessage();
        }



        // Retry mechanism for Service Worker registration.
        async function registerServiceWorker(swUrl, { scope, retries = 3, updateViaCache = "none" } = {}) {
          try {
            const registration = await navigator.serviceWorker.register(swUrl, { updateViaCache, scope });
            return registration;
          } catch (error) {
            if (retries > 0) {
              await new Promise(resolve => setTimeout(resolve, 1000));
              return registerServiceWorker(swUrl, { scope, retries: retries - 1, updateViaCache });
            } else {
              throw error;
            }
          }
        }
    })();
